import { readFile, writeFile } from "node:fs/promises";

const [sourcePath, outputPath] = process.argv.slice(2);
if (!sourcePath || !outputPath) {
  throw new Error(
    "usage: generate-industry-reference.mjs <catalog.json> <output.md>",
  );
}

const catalog = JSON.parse(await readFile(sourcePath, "utf8"));
const lines = [
  "# GEOEval Industry Catalog Reference",
  "",
  "> Generated from the Brand Knowledge executable catalog. Do not edit this file manually.",
  "",
  `- Catalog: \`${catalog.catalogId}@${catalog.version}\``,
  `- Content hash: \`${catalog.contentHash}\``,
  "",
];

for (const primary of catalog.primaryIndustries) {
  lines.push(
    `## ${primary.id} ${primary.label}`,
    "",
    "| ID | 二级行业 | Recommendation subject |",
    "| --- | --- | --- |",
  );
  for (const secondary of primary.secondaryIndustries) {
    lines.push(
      `| ${secondary.id} | ${secondary.label} | ${secondary.recommendationSubject} |`,
    );
  }
  lines.push("");
}

await writeFile(outputPath, `${lines.join("\n").trimEnd()}\n`);
